    (NUM_OF_ENTRIES <= 1) ? 1 : $clog2(NUM_OF_ENTRIES);

logic [CHOSEN_SLOT_WIDTH-1:0] chosen_slot;
logic [CHOSEN_SLOT_WIDTH-1:0] chosen_slot_on_push;
logic [NUM_OF_ENTRIES-1:0] chosen_slot_candidates;

// Select an entry containing push_id after an accepted push.
// Multi-push reuses a match when one exists.
// Single-push allocates a free slot when one exists; otherwise,
// an accepted push must already have a matching entry.
assign chosen_slot_candidates =
    SUPPORT_MULTI_PUSH
        ? ((|push_match) ? push_match : push_ptr)
        : ((|push_ptr)   ? push_ptr   : push_match);

always_comb begin
    chosen_slot_on_push = '0;
    for (int s = NUM_OF_ENTRIES - 1; s >= 0; s--) begin
        if (chosen_slot_candidates[s])
            chosen_slot_on_push = CHOSEN_SLOT_WIDTH'(s);
    end
end

always_ff @(posedge clk) begin
    if (rst)
        chosen_slot <= '0;
    else if (!chosen && chosen_push && push)
        chosen_slot <= chosen_slot_on_push;
end
```

